// The --dry stub scripts (packages/exp/fixtures/dry): regenerated byte-identically; every edit step
// applies to its base exactly like `git apply` of the source patch; valid for SAFE's stub runner.
import { spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { parseStubScript } from '@fiks/repair';
import { describe, expect, test } from 'vitest';
import {
  buildStubs,
  OUT,
  patchToEdits,
  REPRO_AGENT_TEST,
  ROOT,
  serialize,
} from '../scripts/gen-dry-stubs.ts';
import { DEV_BUILTIN } from '../src/inputs.ts';
import { tmp } from './support/harness.ts';

const SHOP = join(ROOT, '.work', 'shop-mcp');
const TRACKER = join(ROOT, '.work', 'tracker-mcp');
const show = (repo: string, ref: string, path: string) => {
  const r = spawnSync('git', ['-C', repo, 'show', `${ref}^{commit}:${path}`], { encoding: 'utf8' });
  if (r.status !== 0) throw new Error(`git show ${ref}:${path} in ${repo}: ${r.stderr}`);
  return r.stdout;
};

/** `git apply` of `patch` on the files of `repo` at `ref`, in a scratch repo. */
function gitApply(repo: string, ref: string, patch: string, paths: string[]): Record<string, string> {
  const dir = tmp('apply');
  spawnSync('git', ['-C', dir, 'init', '-q']);
  for (const p of paths) {
    mkdirSync(dirname(join(dir, p)), { recursive: true });
    writeFileSync(join(dir, p), show(repo, ref, p));
  }
  writeFileSync(join(dir, 'x.patch'), patch);
  const r = spawnSync('git', ['-C', dir, 'apply', 'x.patch'], { encoding: 'utf8' });
  if (r.status !== 0) throw new Error(`git apply failed: ${r.stderr}`);
  return Object.fromEntries(paths.map((p) => [p, readFileSync(join(dir, p), 'utf8')]));
}

/** What SAFE's stub runner does with an edit step: replace the first occurrence. */
function applyEdits(
  repo: string,
  ref: string,
  steps: { op: string; path: string; oldString?: string; newString?: string }[],
): Record<string, string> {
  const files: Record<string, string> = {};
  for (const s of steps) {
    files[s.path] ??= show(repo, ref, s.path);
    const before = files[s.path] as string;
    const old = s.oldString as string;
    expect(before.split(old).length - 1, `${s.path}: oldString must occur exactly once`).toBe(1);
    files[s.path] = before.replace(old, () => s.newString as string);
  }
  return files;
}

describe('dry stub fixtures', () => {
  test('regenerate byte-identically and parse as SAFE stub scripts', () => {
    const want = buildStubs();
    expect(readdirSync(OUT).sort()).toEqual(Object.keys(want).sort());
    for (const [name, body] of Object.entries(want)) {
      expect(readFileSync(join(OUT, name), 'utf8'), name).toBe(serialize(body));
      expect(() => parseStubScript(JSON.parse(readFileSync(join(OUT, name), 'utf8')))).not.toThrow();
    }
    // One stub per built-in dev drift, plus the REPRO-AGENT test and the no-op.
    for (const d of DEV_BUILTIN) expect(existsSync(join(OUT, `${d.id}.json`)), d.id).toBe(true);
  });

  test('only src/ is edited; DEV-X1 and noop make no edit', () => {
    for (const [name, body] of Object.entries(buildStubs())) {
      const steps = (body as { steps: { op: string; path: string }[] }).steps;
      if (name === 'repro-agent.json') continue;
      for (const s of steps) expect(s.path, name).toMatch(/^src\/.+\.ts$/);
    }
    expect((buildStubs()['DEV-X1.json'] as { steps: unknown[] }).steps).toEqual([]);
    expect((buildStubs()['noop.json'] as { steps: unknown[] }).steps).toEqual([]);
  });

  test('the REPRO-AGENT stub writes one test under test/ that loads .alerts/<id>.json via test/fiks/run.ts', () => {
    const s = buildStubs()['repro-agent.json'] as { steps: { op: string; path: string; content: string }[] };
    expect(s.steps).toHaveLength(1);
    expect(s.steps[0]?.op).toBe('newTest');
    expect(s.steps[0]?.path).toMatch(/^test\/[^/]+\.test\.ts$/);
    expect(REPRO_AGENT_TEST).toContain("from './fiks/run.ts'");
    expect(REPRO_AGENT_TEST).toContain('.alerts/');
    expect(REPRO_AGENT_TEST).not.toMatch(/"upstream"|exchanges/);
  });

  describe.runIf(existsSync(join(SHOP, '.git')))(
    'shop stubs on seed-v1 (oracle patches; not the fix commits)',
    () => {
      for (const n of [1, 3, 4, 5]) {
        test(`D${n}: edit steps == git apply of packages/cli/test/oracles/D${n}.patch on seed-v1`, () => {
          const patch = readFileSync(join(ROOT, `packages/cli/test/oracles/D${n}.patch`), 'utf8');
          const steps = patchToEdits(patch);
          const paths = [...new Set(steps.map((s) => s.path))];
          expect(applyEdits(SHOP, 'seed-v1', steps)).toEqual(gitApply(SHOP, 'seed-v1', patch, paths));
        });
      }
      test('D2: a P1 clamp of price to the get_product contract range [20, 2000]', () => {
        const s = buildStubs()['D2.json'] as {
          steps: { op: string; path: string; oldString: string; newString: string }[];
        };
        const out = applyEdits(SHOP, 'seed-v1', s.steps)['src/tools/get_product.ts'] as string;
        expect(out).toContain('Math.min(Math.max(p.price ?? 20, 20), 2000)');
        const contracts = JSON.parse(
          readFileSync(join(ROOT, 'packages/contracts/contracts/shop-mcp.contracts.json'), 'utf8'),
        );
        const range = JSON.stringify(contracts).match(/"price\.range"[^}]*"min": ?(\d+)[^}]*"max": ?(\d+)/);
        expect(range?.slice(1, 3)).toEqual(['20', '2000']);
      });
    },
  );

  describe.runIf(existsSync(join(TRACKER, '.git')))('tracker stub on dev-tracker-stub', () => {
    test("TRK-DEV-1: edit steps == git apply of DOM2's ref A", () => {
      const patch = readFileSync(
        join(ROOT, 'packages/vendor-tracker/fixtures/driftpkgs/TRK-DEV-1/refA.patch'),
        'utf8',
      );
      const steps = patchToEdits(patch);
      const paths = [...new Set(steps.map((s) => s.path))];
      expect(applyEdits(TRACKER, 'dev-tracker-stub', steps)).toEqual(
        gitApply(TRACKER, 'dev-tracker-stub', patch, paths),
      );
    });
  });
});
